const id_table = '#t_' + this.domCont.id;
const table = $(id_table).DataTable();

const tableData = table.rows().data().toArray();
let keysFromTable = [];
tableData.forEach(el => {
    keysFromTable.push(el[0]);
});

idlist.forEach(idFromAttr => {
    let cellPosition = keysFromTable.indexOf(idFromAttr);
    if (cellPosition === -1) return;
    $(table.row(cellPosition).node()).addClass('selected');
    execEventBinded(this.domCont.id.slice(2), "cellclick", {keyField: idFromAttr});
});

const id_table = '#t_' + this.domCont.id;
const table = $(id_table).DataTable();
const number = table.column( 0 ).data().length;
for (i = 0; i < number; i++) {
  if ( $(table.row( i ).node()).hasClass('selected') ) {
    $(table.row( i ).node()).removeClass('selected');
  }
}

